package plates.ui

import kotlinx.browser.document
import org.w3c.dom.Element
import org.w3c.dom.Node
import plates.render.PlateLayer

private const val SVG_NS = "http://www.w3.org/2000/svg"

/** Gives [el] exactly [from]'s attributes, touching only those that differ. */
private fun syncAttributes(el: Element, from: Element) {
    val stale = (0 until el.attributes.length).mapNotNull { el.attributes.item(it)?.name }.filter { !from.hasAttribute(it) }
    stale.forEach(el::removeAttribute)
    for (i in 0 until from.attributes.length) {
        val a = from.attributes.item(i) ?: continue
        if (el.getAttribute(a.name) != a.value) el.setAttribute(a.name, a.value)
    }
}

/**
 * Makes [live]'s children match [next]'s, keeping every live node whose kind and tag agree with the one at its
 * position and only updating its attributes and text. An `<image>` under a fading group stays the same node, so it
 * is never fetched or decoded again; a node that does not match is replaced by [next]'s own (moved, not cloned).
 */
fun reconcile(live: Node, next: Node) {
    val want = (0 until next.childNodes.length).mapNotNull { next.childNodes.item(it) }
    want.forEachIndexed { i, n ->
        val have = live.childNodes.item(i)
        when {
            have == null -> live.appendChild(n)
            have.nodeType != n.nodeType || have.nodeName != n.nodeName -> live.replaceChild(n, have)
            n.nodeType == Node.ELEMENT_NODE -> { syncAttributes(have as Element, n as Element); reconcile(have, n) }
            have.nodeValue != n.nodeValue -> have.nodeValue = n.nodeValue
        }
    }
    while (live.childNodes.length > want.size) live.removeChild(live.lastChild!!)
}

/**
 * [D1][H14] A plate's retained SVG in the page: one `<svg>` holding a `<g>` per layer, created once. Each [paint]
 * touches only the layers whose markup changed (see [SvgLayers]), and patches those in place ([reconcile]) rather
 * than replacing them: typing never rebuilds the frame or the artwork, and a part fading in keeps its nodes, so the
 * flag and decal images are fetched and decoded once per spec, not once per keystroke or animation frame.
 */
class PlateSurface(idPrefix: String, resolveAsset: (String, String) -> String = { p, a -> "packages/$p/$a" }) {
    private val layers = SvgLayers(idPrefix, resolveAsset)

    /** Off-document: each new markup is parsed here, then reconciled into the live layer. */
    private val scratch = document.createElementNS(SVG_NS, "g")
    val element: Element = document.createElementNS(SVG_NS, "svg").also { it.setAttribute("style", "width:100%;height:auto;display:block") }
    private val groups = PlateLayer.entries.associateWith { l ->
        document.createElementNS(SVG_NS, "g").also { it.setAttribute("data-layer", l.name); element.appendChild(it) }
    }

    /** Paints [p]; returns the layers it had to rewrite. */
    fun paint(p: PlatePicture): List<PlateLayer> {
        val delta = layers.diff(p)
        delta.viewBox?.let { element.setAttribute("viewBox", it) }
        delta.layers.forEach { (l, markup) ->
            scratch.innerHTML = markup
            reconcile(groups.getValue(l), scratch)
        }
        return delta.layers.map { it.first }
    }
}

/**
 * Repaints a canvas once per animation frame while it [PlateCanvas.animating], and no more: [request] asks for a
 * frame (coalescing repeats), and each frame paints the canvas's picture at one time and asks again if it still moves.
 */
class FrameLoop(private val canvas: PlateCanvas, private val paint: (PlatePicture) -> Unit) {
    private var pending = false
    private var stopped = false

    fun request() {
        if (pending || stopped) return
        pending = true
        kotlinx.browser.window.requestAnimationFrame { frame() }
    }

    /** Paints now, then keeps going while anything moves. */
    fun frame() {
        pending = false
        if (stopped) return
        val t = pageNow()
        paint(canvas.picture(t))
        if (canvas.isAnimatingAt(t)) request()
    }

    fun stop() {
        stopped = true
    }
}
